/**
 * Unit tests for git bundle v2 parsing, using a real `git bundle create`
 * fixture (generated by the system git in test setup, exactly what an
 * rngit node returns from `/git/fetch`).
 */
import { strict as assert } from "node:assert";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, test } from "node:test";
import { emptyPack, parseBundle } from "../src/bundle.js";

/** Shared git env for fixture creation. */
const ENV = {
  ...process.env,
  GIT_AUTHOR_NAME: "Test",
  GIT_AUTHOR_EMAIL: "test@example.com",
  GIT_COMMITTER_NAME: "Test",
  GIT_COMMITTER_EMAIL: "test@example.com",
};

/**
 * Creates a small git repo with two commits and a tag. Returns the fixture
 * paths plus the repo's refs.
 *
 * @returns {{ dir: string, fullBundle: string, thinBundle: string, headSha: string, refs: Map<string,string> }}
 */
function makeFixture() {
  const dir = mkdtempSync(join(tmpdir(), "rngit-bundle-"));
  const git = (/** @type {string[]} */ ...args) =>
    execFileSync("git", ["-C", dir, ...args], { env: ENV })
      .toString()
      .trim();
  git("init", "-q", "-b", "main");
  git("config", "user.name", "Test");
  git("config", "user.email", "test@example.com");
  git("commit", "--allow-empty", "-m", "one");
  git("commit", "--allow-empty", "-m", "two");
  git("tag", "v1.0");

  const fullBundle = join(dir, "full.bundle");
  execFileSync(
    "git",
    ["-C", dir, "bundle", "create", "-q", fullBundle, "--all"],
    { env: ENV },
  );

  // A thin bundle: only the second commit, with the first as prerequisite.
  const thinBundle = join(dir, "thin.bundle");
  const firstSha = git("rev-parse", "HEAD~1");
  execFileSync(
    "git",
    ["-C", dir, "bundle", "create", "-q", thinBundle, "main", `^${firstSha}`],
    { env: ENV },
  );

  /** @type {Map<string,string>} */
  const refs = new Map();
  for (const line of git(
    "for-each-ref",
    "--format",
    "%(objectname) %(refname)",
  ).split("\n")) {
    const sep = line.indexOf(" ");
    refs.set(line.slice(sep + 1), line.slice(0, sep));
  }
  return {
    dir,
    fullBundle,
    thinBundle,
    headSha: git("rev-parse", "HEAD"),
    refs,
  };
}

describe("parseBundle", () => {
  test("parses a full bundle from git bundle create", () => {
    const { dir, fullBundle, refs } = makeFixture();
    try {
      const parsed = parseBundle(new Uint8Array(readFileSync(fullBundle)));
      assert.equal(parsed.prerequisites.length, 0);
      assert.equal(
        parsed.refs.get("refs/heads/main"),
        refs.get("refs/heads/main"),
      );
      assert.equal(
        parsed.refs.get("refs/tags/v1.0"),
        refs.get("refs/tags/v1.0"),
      );
      assert.ok(parsed.pack.length > 0);
      assert.equal(Buffer.from(parsed.pack.subarray(0, 4)).toString(), "PACK");
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  test("parses a thin bundle with prerequisites", () => {
    const { dir, thinBundle, headSha } = makeFixture();
    try {
      const parsed = parseBundle(new Uint8Array(readFileSync(thinBundle)));
      assert.equal(parsed.prerequisites.length, 1);
      assert.equal(parsed.prerequisites[0].length, 40);
      assert.ok(parsed.refs.size >= 1);
      assert.ok([...parsed.refs.values()].every((sha) => sha.length === 40));
      assert.equal([...parsed.refs.values()][0], headSha);
      assert.ok(parsed.pack.length > 0);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  test("rejects non-bundles", () => {
    assert.throws(() => parseBundle(new TextEncoder().encode("PACK junk")));
    assert.throws(() =>
      parseBundle(new TextEncoder().encode("# v2 git bundle\n")),
    );
  });
});

describe("emptyPack", () => {
  test("produces a valid zero-object packfile", async () => {
    const pack = await emptyPack();
    assert.equal(pack.length, 32);
    assert.equal(Buffer.from(pack.subarray(0, 4)).toString(), "PACK");
    assert.equal(Buffer.from(pack.subarray(4, 8)).toString("hex"), "00000002");
    assert.equal(Buffer.from(pack.subarray(8, 12)).toString("hex"), "00000000");
    // SHA-1 trailer over the 12 header bytes (fixed vector, verified with
    // the system sha1 tool).
    assert.equal(
      Buffer.from(pack.subarray(12)).toString("hex"),
      "029d08823bd8a8eab510ad6ac75c823cfd3ed31e",
    );
  });
});
